"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["22697"],{14835(e,t,a){a.r(t),a.d(t,{metadata:()=>i,default:()=>u,frontMatter:()=>o,contentTitle:()=>p,toc:()=>h,assets:()=>d});var i=JSON.parse('{"id":"nhcx/v1/api/registry/endpoints/registry-participant-details","title":"Submit the participant details (v2 search)","description":"V2 variant of participant search: takes participant_code and returns the matching full registry records.","source":"@site/docs/nhcx/v1/api/registry/endpoints/registry-participant-details.mdx","sourceDirName":"nhcx/v1/api/registry/endpoints","slug":"/nhcx/v1/api/registry/endpoints/registry-participant-details","permalink":"/docs/pr-30/docs/nhcx/v1/api/registry/endpoints/registry-participant-details","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Submit the participant details (v2 search)","sidebar_label":"Submit the participant details (v2 search)","sidebar_class_name":"api-method api-method--post","description":"V2 variant of participant search: takes participant_code and returns the matching full registry records.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","source":"nhcx-registry.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Submit the participant search","permalink":"/docs/pr-30/docs/nhcx/v1/api/registry/endpoints/registry-participant-search"},"next":{"title":"Fetch participants list","permalink":"/docs/pr-30/docs/nhcx/v1/api/registry/endpoints/registry-fetch-participants-list"}}'),n=a(62540),r=a(43023),s=a(75064),c=JSON.parse('{"id":"registry_participant_details","module":"Participant registry","moduleId":"registry","kind":"operation","method":"POST","path":"/participant/details","server":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","servers":[{"url":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","description":"Sandbox, Participant service."},{"url":"https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice","description":"Production."}],"summary":"Participant details (v2 search)","title":"Submit the participant details (v2 search)","description":"V2 variant of participant search: takes participant_code and returns the matching full registry records.\\n\\n### Business purpose\\n\\nThis is the second of two endpoints that read a single participant by code. It exists as the v2 generation of the registry lookup (operationId participantV2SearchPost) and serves the same business need as /participant/search: confirming that a counterparty exists, is active, holds the expected role and publishes an encryption certificate and callback endpoint before any encrypted transaction is addressed to it.\\n\\n### When to use\\n\\nUse it wherever /participant/search would be used: after payer discovery via /fetch/participants/list, before the first JWE to a new recipient, or to verify your own record after an update. The OpenAPI gives both endpoints the identical description and the same ParticipantSearchReq and ParticipantSearchResponse schemas, and documents no behavioural difference beyond the operationId; the chapter advises treating them as interchangeable unless your HCX instance says otherwise. Synchronous JSON, no workflow or x-hcx-status codes.\\n\\n### Preconditions\\n\\n- Bearer token from /get/session in bearer_auth with the Bearer prefix; Accept and Content-Type: application/json.\\n- Body per ParticipantSearchReq: participant_code (string, required) in xxxxx@hcx or @sbx form.\\n- Served under the participanthcxservice prefix on the environment gateway base.\\n\\n### Postconditions\\n\\nHTTP 200 with ParticipantSearchResponse: timestamp and a participants array of full participant records (participant_code, linked_registry_codes, participant_name, scheme_code, roles, address, contact fields, status, signing_cert_path, encryption_cert, endpoint_URL, payment_details). Read-only; nothing changes and no callback follows. 400, 404 and 500 return the ErrorResponse envelope with timestamp and error code, message and trace.\\n\\n### Common mistakes\\n\\n- Expecting a different or richer response than /participant/search; the documented schemas are identical.\\n- Using participantcode or participantid instead of participant_code.\\n- Treating encryption_cert (a URI or file path in the schema) as the PEM itself instead of calling /fetch/certs.\\n- Omitting the Accept header or the Bearer prefix.\\n- Hard-coding one of the two lookup paths without a fallback when the instance serves only the other.\\n\\n### Best practices\\n\\n- Wrap both lookup endpoints behind one client function so the path can be switched by configuration.\\n- Check status and roles before choosing a recipient code.\\n- Cache the record and refresh on routing or decryption errors rather than on every transaction.\\n- Do not log payment_details.\\n\\n### Related scenario\\n\\nA payer\'s inbound gateway receives a /v1/claim/submit whose protected header names x-hcx-sender_code 100001@sbx. Before decrypting and processing, its integration calls /participant/details with that participant_code to confirm the sender is a registered provider with status Active and to record participant_name for the adjudication file. The claim is then decrypted with the payer\'s private key and passed to the claims team, whose decision goes back on /v1/claim/on_submit.\\n\\n### Specification\\n\\nChapter [Creating and updating a participant](/docs/nhcx/v1/getting-started/creating-and-updating-a-participant) of the NHCX integration specification.","security":[{"name":"bearerAuth","type":"http","scheme":"bearer","description":"On every NHCX call, the token goes in a header called `bearer_auth`, with the word `Bearer` and a space in front. The sources are not unanimous: the authentication page and the FAQ both write the example as `Authorization`, and the notification endpoint uses `Authorization`. The safe course, and what the adapter does, is to send both headers with the same value."}],"headers":[{"name":"bearer_auth","required":true,"description":"It is `bearer_auth`, not `Authorization`, on NHCX\'s own endpoints.","example":"Bearer <access token>","type":"string"}],"pathParams":[],"queryParams":[],"body":[{"name":"participant_code","type":"string","required":false,"description":"","encrypted":false}],"requestExample":{"participant_code":"100001@sbx"},"responses":[{"status":"200","description":"HTTP 200 with ParticipantSearchResponse: timestamp and a participants array of full participant records (participant_code, linked_registry_codes, participant_name, scheme_code, roles, address, contact fields, status, signing_cert_path, encryption_cert, endpoint_url, payment_details).","example":{"timestamp":1716204567358,"participants":[{"participant_code":"100001@sbx","participant_name":"Demo Multispeciality Hospital","linked_registry_codes":["IN2910001234@hfr"],"roles":["provider"],"status":["Active"],"primaryEmail":"claims@demohospital.example.in","primaryMobile":"9800000000","encryption_cert":"https://registry.example.in/certs/100001.pem","endpoint_url":"https://nhcx.demohospital.example.in"}]}}],"tag":"Other operations","curl":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/participant/details \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"participant_code\\": \\"100001@sbx\\"\\n}\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/participant/details \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"participant_code\\": \\"100001@sbx\\"\\n}\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.post(\\n    \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/participant/details\\",\\n    headers={\\n        \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n        \\"bearer_auth\\": \\"Bearer <access token>\\",\\n        \\"Content-Type\\": \\"application/json\\",\\n    },\\n    json={\\n        \\"participant_code\\": \\"100001@sbx\\"\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node","language":"javascript","code":"const response = await fetch(\\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/participant/details\\", {\\n  method: \\"POST\\",\\n  headers: {\\n    \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n    \\"bearer_auth\\": \\"Bearer <access token>\\",\\n    \\"Content-Type\\": \\"application/json\\",\\n  },\\n  body: JSON.stringify({\\n    \\"participant_code\\": \\"100001@sbx\\"\\n  }),\\n});\\n\\nconsole.log(response.status, await response.text());"}]}');let o={title:"Submit the participant details (v2 search)",sidebar_label:"Submit the participant details (v2 search)",sidebar_class_name:"api-method api-method--post",description:"V2 variant of participant search: takes participant_code and returns the matching full registry records.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",source:"nhcx-registry.yaml",generated:!0},p,d={},h=[];function l(e){return(0,n.jsx)(s.A,{operation:c})}function u(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(l,{...e})}):l(e)}}}]);